//! The characters the quick menu offers, and how they are searched.
//!
//! Both tables are generated by `data/quick/generate.py` from the Unicode and
//! CLDR sources and embedded whole, so the menu works offline and opens without
//! reading anything from disk. They are parsed on first use: the emoji table
//! when the Emoji tab is shown, the full name table only once a symbol search
//! reaches past the curated categories or a name is needed.

use std::{
    collections::{HashMap, HashSet},
    sync::OnceLock,
};

const EMOJI_TSV: &str = include_str!("../../data/quick/emoji.tsv");
const UNICODE_TSV: &str = include_str!("../../data/quick/unicode.tsv");

/// Most results a search shows. Past this the grid only gets harder to scan.
pub const SEARCH_LIMIT: usize = 400;

/// The five Fitzpatrick modifiers, lightest first. Index `0` in the picker is
/// "no modifier", so tone `n` is `SKIN_TONES[n - 1]`.
pub const SKIN_TONES: [char; 5] = [
    '\u{1F3FB}',
    '\u{1F3FC}',
    '\u{1F3FD}',
    '\u{1F3FE}',
    '\u{1F3FF}',
];
const VS16: char = '\u{FE0F}';

/// One cell in the grid.
#[derive(Clone, Debug, PartialEq)]
pub struct Item {
    /// What is shown, and what is inserted.
    pub text: String,
    /// A human name for the footer.
    pub name: String,
}

// -- Emoji -----------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
pub struct Emoji {
    pub group: &'static str,
    pub glyph: &'static str,
    /// Emoji version it was introduced in, as `(major, minor)`.
    pub version: (u8, u8),
    /// Whether it takes a skin-tone modifier after its first code point.
    pub tones: bool,
    pub name: &'static str,
    pub keywords: &'static str,
}

impl Emoji {
    /// The glyph in skin tone `tone` (`0` for none), when it has tones.
    pub fn toned(&self, tone: u8) -> String {
        match (self.tones, tone) {
            (true, 1..=5) => with_tone(self.glyph, SKIN_TONES[usize::from(tone) - 1]),
            _ => self.glyph.to_string(),
        }
    }

    /// A lone code point, optionally followed by the emoji selector — the
    /// kind whose support a font can be asked about reliably.
    pub fn is_single(&self) -> bool {
        let mut chars = self.glyph.chars();
        chars.next().is_some()
            && match chars.next() {
                None => true,
                Some(VS16) => chars.next().is_none(),
                Some(_) => false,
            }
    }

    fn item(&self, tone: u8) -> Item {
        Item {
            text: self.toned(tone),
            name: capitalise(self.name),
        }
    }
}

/// The modifier follows the first code point, replacing an emoji-presentation
/// selector there — the rule the generator checked every toned emoji against.
fn with_tone(glyph: &str, tone: char) -> String {
    let mut chars = glyph.chars();
    let mut toned = String::with_capacity(glyph.len() + 4);
    if let Some(first) = chars.next() {
        toned.push(first);
        toned.push(tone);
    }
    let rest = chars.as_str();
    toned.push_str(rest.strip_prefix(VS16).unwrap_or(rest));
    toned
}

/// Undoes [`with_tone`] closely enough to find the base emoji again: drops the
/// modifiers, so `👍🏽` looks up as `👍`.
fn strip_tones(text: &str) -> String {
    text.chars().filter(|ch| !SKIN_TONES.contains(ch)).collect()
}

pub struct EmojiTable {
    pub emoji: Vec<Emoji>,
    /// Group names in table order, which is the order Unicode presents them.
    pub groups: Vec<&'static str>,
    by_glyph: HashMap<&'static str, usize>,
}

impl EmojiTable {
    fn parse(tsv: &'static str) -> Self {
        let mut emoji = Vec::new();
        let mut groups: Vec<&'static str> = Vec::new();
        for line in tsv.lines() {
            let mut fields = line.split('\t');
            let (Some(group), Some(_subgroup), Some(glyph), Some(version), Some(tones), Some(name)) = (
                fields.next(),
                fields.next(),
                fields.next(),
                fields.next(),
                fields.next(),
                fields.next(),
            ) else {
                continue;
            };
            if groups.last() != Some(&group) {
                groups.push(group);
            }
            emoji.push(Emoji {
                group,
                glyph,
                version: parse_version(version),
                tones: tones == "1",
                name,
                keywords: fields.next().unwrap_or(""),
            });
        }
        let by_glyph = emoji
            .iter()
            .enumerate()
            .map(|(index, emoji)| (emoji.glyph, index))
            .collect();
        Self {
            emoji,
            groups,
            by_glyph,
        }
    }

    /// The emoji `text` is, in any skin tone.
    pub fn find(&self, text: &str) -> Option<&Emoji> {
        self.by_glyph
            .get(text)
            .or_else(|| self.by_glyph.get(strip_tones(text).as_str()))
            .or_else(|| {
                // A toned emoji loses its selector along with the tone.
                let mut base = strip_tones(text);
                let first = base.chars().next()?;
                base.insert(first.len_utf8(), VS16);
                self.by_glyph.get(base.as_str())
            })
            .map(|&index| &self.emoji[index])
    }

    pub fn group_items(
        &self,
        group: &str,
        tone: u8,
        supported: impl Fn(&Emoji) -> bool,
    ) -> Vec<Item> {
        self.emoji
            .iter()
            .filter(|emoji| emoji.group == group && supported(emoji))
            .map(|emoji| emoji.item(tone))
            .collect()
    }

    pub fn search(&self, query: &str, tone: u8, supported: impl Fn(&Emoji) -> bool) -> Vec<Item> {
        let query = Query::new(query);
        if query.is_empty() {
            return Vec::new();
        }
        let mut ranked: Vec<(u8, usize, &Emoji)> = self
            .emoji
            .iter()
            .filter(|emoji| supported(emoji))
            .filter_map(|emoji| {
                query
                    .rank(emoji.name, emoji.keywords)
                    .map(|rank| (rank, emoji.name.len(), emoji))
            })
            .collect();
        // Stable, so equally good matches keep Unicode's order.
        ranked.sort_by_key(|(rank, length, _)| (*rank, *length));
        ranked
            .into_iter()
            .take(SEARCH_LIMIT)
            .map(|(_, _, emoji)| emoji.item(tone))
            .collect()
    }

    /// Emoji versions in the table, oldest first, each with its lone-code-point
    /// emoji — what a font's support for that version is judged by.
    pub fn versions(&self) -> Vec<((u8, u8), Vec<&Emoji>)> {
        let mut versions: Vec<((u8, u8), Vec<&Emoji>)> = Vec::new();
        for emoji in &self.emoji {
            match versions
                .iter_mut()
                .find(|(version, _)| *version == emoji.version)
            {
                Some((_, members)) => members.push(emoji),
                None => versions.push((emoji.version, vec![emoji])),
            }
        }
        for (_, members) in &mut versions {
            members.retain(|emoji| emoji.is_single());
        }
        versions.sort_by_key(|(version, _)| *version);
        versions
    }
}

fn parse_version(version: &str) -> (u8, u8) {
    let mut parts = version.split('.').map(|part| part.parse().unwrap_or(0));
    (parts.next().unwrap_or(0), parts.next().unwrap_or(0))
}

pub fn emoji() -> &'static EmojiTable {
    static TABLE: OnceLock<EmojiTable> = OnceLock::new();
    TABLE.get_or_init(|| EmojiTable::parse(EMOJI_TSV))
}

/// A short icon for each Unicode emoji group, for the category bar.
pub fn emoji_group_icon(group: &str) -> &'static str {
    match group {
        "Smileys & Emotion" => "😀",
        "People & Body" => "👋",
        "Animals & Nature" => "🐻",
        "Food & Drink" => "🍔",
        "Travel & Places" => "🚗",
        "Activities" => "⚽",
        "Objects" => "💡",
        "Symbols" => "🔣",
        "Flags" => "🏁",
        _ => "❔",
    }
}

// -- Unicode names ---------------------------------------------------------

#[derive(Clone, Copy, Debug)]
pub struct Named {
    pub code: u32,
    pub name: &'static str,
    pub keywords: &'static str,
}

impl Named {
    fn item(&self) -> Option<Item> {
        Some(Item {
            text: char::from_u32(self.code)?.to_string(),
            name: capitalise(&self.name.to_lowercase()),
        })
    }
}

pub struct UnicodeTable {
    /// Sorted by code point, as the source is.
    entries: Vec<Named>,
}

impl UnicodeTable {
    fn parse(tsv: &'static str) -> Self {
        let entries = tsv
            .lines()
            .filter_map(|line| {
                let mut fields = line.split('\t');
                let code = u32::from_str_radix(fields.next()?, 16).ok()?;
                let name = fields.next()?;
                Some(Named {
                    code,
                    name,
                    keywords: fields.next().unwrap_or(""),
                })
            })
            .collect();
        Self { entries }
    }

    pub fn get(&self, code: u32) -> Option<&Named> {
        self.entries
            .binary_search_by_key(&code, |named| named.code)
            .ok()
            .map(|index| &self.entries[index])
    }

    fn search(&self, query: &Query) -> Vec<(u8, &Named)> {
        let mut ranked: Vec<(u8, usize, &Named)> = self
            .entries
            .iter()
            .filter_map(|named| {
                query
                    .rank(named.name, named.keywords)
                    .map(|rank| (rank, named.name.len(), named))
            })
            .collect();
        ranked.sort_by_key(|(rank, length, _)| (*rank, *length));
        ranked
            .into_iter()
            .map(|(rank, _, named)| (rank, named))
            .collect()
    }
}

pub fn unicode() -> &'static UnicodeTable {
    static TABLE: OnceLock<UnicodeTable> = OnceLock::new();
    TABLE.get_or_init(|| UnicodeTable::parse(UNICODE_TSV))
}

// -- Symbols ---------------------------------------------------------------

enum Span {
    Chars(&'static str),
    Range(u32, u32),
}

pub struct SymbolCategory {
    pub name: &'static str,
    pub icon: &'static str,
    spans: &'static [Span],
}

impl SymbolCategory {
    fn chars(&self) -> impl Iterator<Item = char> + '_ {
        self.spans
            .iter()
            .flat_map(|span| -> Box<dyn Iterator<Item = char>> {
                match span {
                    Span::Chars(chars) => Box::new(chars.chars()),
                    Span::Range(start, end) => Box::new((*start..=*end).filter_map(char::from_u32)),
                }
            })
    }

    /// Every assigned character in the category, named. Ranges may cross
    /// unassigned code points; those have no name and are left out.
    pub fn items(&self) -> Vec<Item> {
        let table = unicode();
        let mut seen = Vec::new();
        self.chars()
            .filter(|ch| {
                let fresh = !seen.contains(ch);
                seen.push(*ch);
                fresh
            })
            .filter_map(|ch| table.get(u32::from(ch))?.item())
            .collect()
    }
}

