/// Symbol search over all of Unicode by name, with the curated categories
/// first among equally good matches, since they hold what is usually wanted. A query that *is* a
/// character, or spells one as `U+2192` or `2192`, finds it directly.
pub fn search_symbols(query: &str) -> Vec<Item> {
    let table = unicode();
    let mut results: Vec<Item> = Vec::new();
    let mut seen: Vec<u32> = Vec::new();

    if let Some(code) = code_point(query.trim())
        && let Some(item) = table.get(code).and_then(Named::item)
    {
        seen.push(code);
        results.push(item);
    }
    let parsed = Query::new(query);
    if parsed.is_empty() {
        return results;
    }

    let curated: HashSet<u32> = SYMBOL_CATEGORIES
        .iter()
        .flat_map(SymbolCategory::chars)
        .map(u32::from)
        .collect();
    let mut matches = table.search(&parsed);
    // Unicode names are long and literal, so a name that happens to start
    // with the query ("RIGHT ARROW WITH SMALL CIRCLE") is no better a match
    // than one holding every word ("RIGHTWARDS ARROW"), or one with the query
    // as a keyword: those ranks are one tier, ordered curated first and then
    // shortest. An exact name elsewhere in Unicode still beats a curated
    // character that merely shares the start of a keyword.
    matches.sort_by_key(|(rank, named)| {
        let tier = match rank {
            0 => 0,
            1..=3 => 1,
            _ => 2,
        };
        (tier, !curated.contains(&named.code), named.name.len())
    });

    for (_, named) in matches {
        if results.len() >= SEARCH_LIMIT {
            break;
        }
        if seen.contains(&named.code) {
            continue;
        }
        seen.push(named.code);
        results.extend(named.item());
    }
    results
}

/// `→`, `U+2192`, `u2192` or `0x2192`. A bare hex word only counts with at
/// least four digits, so a search for "face" or "add" is not taken for one.
fn code_point(query: &str) -> Option<u32> {
    let mut chars = query.chars();
    if let (Some(ch), None) = (chars.next(), chars.next())
        && !ch.is_ascii_alphanumeric()
    {
        return Some(u32::from(ch));
    }
    let lower = query.to_ascii_lowercase();
    let (hex, prefixed) = match ["u+", "0x", "u"]
        .iter()
        .find_map(|prefix| lower.strip_prefix(prefix))
    {
        Some(hex) => (hex, true),
        None => (lower.as_str(), false),
    };
    let plausible = (1..=6).contains(&hex.len()) && (prefixed || hex.len() >= 4);
    if !plausible || !hex.chars().all(|ch| ch.is_ascii_hexdigit()) {
        return None;
    }
    // A hex-looking word ("cafe", "beef") is still more likely a word.
    if !prefixed && hex.chars().all(|ch| ch.is_ascii_alphabetic()) {
        return None;
    }
    u32::from_str_radix(hex, 16).ok()
}

// -- Matching --------------------------------------------------------------

/// A search, split into words that each have to start a word of the name or
/// the keywords.
struct Query {
    whole: String,
    words: Vec<String>,
}

impl Query {
    fn new(query: &str) -> Self {
        let whole = query.trim().to_lowercase();
        let words = split_words(&whole).map(str::to_string).collect();
        Self { whole, words }
    }

    fn is_empty(&self) -> bool {
        self.words.is_empty()
    }

    /// Lower is better; `None` is no match.
    ///
    /// 0 the name is the query, 1 the query is one of the keywords, 2 the name
    /// starts with it, 3 every word starts a word of the name, 4 every word
    /// starts a word of the name or keywords.
    ///
    /// A keyword said in full beats a name that merely starts the same way:
    /// "lol" is 😂's keyword, and only the start of "lollipop".
    fn rank(&self, name: &str, keywords: &str) -> Option<u8> {
        if name.eq_ignore_ascii_case(&self.whole) {
            return Some(0);
        }
        if split_words(keywords).any(|keyword| keyword.eq_ignore_ascii_case(&self.whole)) {
            return Some(1);
        }
        if starts_with_ignore_case(name, &self.whole) {
            return Some(2);
        }
        let in_name = |word: &String| {
            split_words(name).any(|candidate| starts_with_ignore_case(candidate, word))
        };
        if self.words.iter().all(in_name) {
            return Some(3);
        }
        let anywhere = |word: &String| {
            in_name(word)
                || split_words(keywords).any(|candidate| starts_with_ignore_case(candidate, word))
        };
        self.words.iter().all(anywhere).then_some(4)
    }
}

fn split_words(text: &str) -> impl Iterator<Item = &str> {
    text.split(|ch: char| !ch.is_alphanumeric())
        .filter(|word| !word.is_empty())
}

/// ASCII case folding is enough: Unicode names are uppercase ASCII, and the
/// emoji names are lowercase already.
fn starts_with_ignore_case(text: &str, prefix: &str) -> bool {
    text.len() >= prefix.len()
        && text.is_char_boundary(prefix.len())
        && text[..prefix.len()].eq_ignore_ascii_case(prefix)
}

fn capitalise(text: &str) -> String {
    let mut chars = text.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().chain(chars).collect(),
        None => String::new(),
    }
}

/// The footer name of any text the menu may have inserted before: an emoji in
/// any tone, or a single character.
pub fn name_of(text: &str) -> String {
    if let Some(emoji) = emoji().find(text) {
        return capitalise(emoji.name);
    }
    let mut chars = text.chars();
    match (chars.next(), chars.next()) {
        (Some(ch), None) => unicode()
            .get(u32::from(ch))
            .and_then(Named::item)
            .map(|item| item.name)
            .unwrap_or_default(),
        _ => String::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_parse_whole() {
        let table = emoji();
        assert!(table.emoji.len() > 1500);
        assert_eq!(table.groups.first(), Some(&"Smileys & Emotion"));
        assert!(table.groups.contains(&"Flags"));
        assert!(!table.groups.contains(&"Component"));
        assert_eq!(
            unicode().get(0x2192).map(|named| named.name),
            Some("RIGHTWARDS ARROW")
        );
    }

    #[test]
    fn every_group_has_an_icon() {
        for group in &emoji().groups {
            assert_ne!(emoji_group_icon(group), "❔", "{group}");
        }
    }

    #[test]
    fn skin_tones_apply_and_are_found_again() {
        let table = emoji();
        let thumbs = table.find("👍").expect("thumbs up");
        assert!(thumbs.tones);
        assert_eq!(thumbs.toned(3), "👍🏽");
        assert_eq!(thumbs.toned(0), "👍");

        // The selector after the first code point makes way for the tone.
        let hand = table.find("🖐️").expect("hand with fingers splayed");
        assert_eq!(hand.toned(1), "🖐🏻");
        assert_eq!(table.find("🖐🏻").map(|emoji| emoji.glyph), Some(hand.glyph));

        let grinning = table.find("😀").expect("grinning face");
        assert!(!grinning.tones);
        assert_eq!(grinning.toned(4), "😀");
    }

    #[test]
    fn emoji_search_uses_names_and_keywords() {
        let results = emoji().search("lol", 0, |_| true);
        assert_ne!(results[0].text, "🍭", "a keyword said in full comes first");
        assert!(results.iter().any(|item| item.text == "😂"));

        let results = emoji().search("thumbs up", 2, |_| true);
        assert_eq!(results.first().map(|item| item.text.as_str()), Some("👍🏼"));
        assert_eq!(results[0].name, "Thumbs up");

        assert!(emoji().search("   ", 0, |_| true).is_empty());
        assert!(emoji().search("zzqqxx", 0, |_| true).is_empty());
    }

    #[test]
    fn symbol_search_favours_the_curated_set() {
        let results = search_symbols("right arrow");
        let first = results.first().expect("a match");
        assert_eq!(first.text, "→");
        assert_eq!(first.name, "Rightwards arrow");

        // Beyond the curated categories.
        assert!(
            search_symbols("snowman")
                .iter()
                .any(|item| item.text == "☃")
        );
        assert!(
            search_symbols("hiragana letter a")
                .iter()
                .any(|item| item.text == "あ")
        );
    }

    #[test]
    fn a_code_point_is_found_directly() {
        assert_eq!(search_symbols("U+2192")[0].text, "→");
        assert_eq!(search_symbols("2192")[0].text, "→");
        assert_eq!(search_symbols("→")[0].text, "→");
        assert_eq!(code_point("face"), None);
        assert_eq!(code_point("add"), None);
        assert_eq!(code_point("12"), None);
        assert_eq!(code_point("u+41"), Some(0x41));
    }

    #[test]
    fn ranking_prefers_whole_then_prefix_then_words() {
        let query = Query::new("heart");
        assert_eq!(query.rank("heart", ""), Some(0));
        assert_eq!(query.rank("heart suit", ""), Some(2));
        assert_eq!(query.rank("black heart suit", ""), Some(3));
        assert_eq!(query.rank("red suit", "heartfelt love"), Some(4));
        assert_eq!(query.rank("red suit", "love heart"), Some(1));
        assert_eq!(query.rank("red suit", "love"), None);
    }

    #[test]
    fn categories_hold_only_named_characters() {
        for category in SYMBOL_CATEGORIES {
            let items = category.items();
            assert!(!items.is_empty(), "{}", category.name);
            assert!(
                items.iter().all(|item| !item.name.is_empty()),
                "{}",
                category.name
            );
        }
        let currency = SYMBOL_CATEGORIES[1].items();
        assert!(currency.iter().any(|item| item.text == "€"));
        assert!(currency.iter().any(|item| item.text == "₿"));
    }

    #[test]
    fn names_are_found_for_recent_items() {
        assert_eq!(name_of("→"), "Rightwards arrow");
        assert_eq!(name_of("👍🏿"), "Thumbs up");
        assert_eq!(name_of("ab"), "");
    }

    #[test]
    fn versions_list_lone_code_points_only() {
        let versions = emoji().versions();
        assert!(versions.windows(2).all(|pair| pair[0].0 < pair[1].0));
        for (_, members) in &versions {
            assert!(members.iter().all(|emoji| emoji.is_single()));
        }
    }
}
